<section class="garden-card"><h2>Team delivery queue</h2><p>Use this page to assign and complete individual service jobs and maintenance visits. Landscaping projects share these job records, but their inspections, quotation approvals and financial stages are managed in the project workspace.</p><a href="<?= base_url('garden/projects'); ?>">Open landscaping project board →</a></section>
<p class="garden-muted">Pending service work from sales, paid online orders, bundles and recurring schedules. Dates remain requests until the team confirms the assignment. Showing the latest 250 jobs.</p>
<?php foreach ($garden_work as $job): ?><article class="garden-card" id="job-<?= (int)$job->id; ?>"><h2><?= htmlspecialchars($job->title); ?></h2>
<p><?= htmlspecialchars($job->customer_name ?? ''); ?> · <?= htmlspecialchars($job->job_code.' · '.ucwords(str_replace('_',' ',$job->status))); ?></p>
<p><?= nl2br(htmlspecialchars($job->description ?? '')); ?></p><p><?= htmlspecialchars($job->scheduled_date ?? 'No Visit Date'); ?> · <?= htmlspecialchars($job->engineer ?? 'Unassigned'); ?></p>
<?php if (isset($garden_project_ids[$job->id])): ?><a class="garden-button" href="<?= base_url('garden/project/'.(int)$job->id); ?>">Open Project Workspace</a><?php endif; ?>
<?php if (!isset($garden_project_ids[$job->id]) && get_instance()->permissions('service_jobs_edit') && !in_array($job->status,['completed','cancelled'],true)): ?>
<details><summary class="garden-disclosure-toggle">Assign or Reschedule</summary><form method="post" action="<?= base_url('garden/work_assign'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= (int)$job->id; ?>">
<div class="garden-grid"><label>Team Member<select name="assigned_user_id" data-garden-select hidden><option value="">Unassigned</option><?php foreach ($garden_staff as $staff): ?><option value="<?= (int)$staff->id; ?>" <?= (int)$job->assigned_user_id===(int)$staff->id ? 'selected' : ''; ?>><?= htmlspecialchars($staff->username); ?></option><?php endforeach; ?></select></label>
<label>Visit Date<input type="date" name="scheduled_date" value="<?= htmlspecialchars($job->scheduled_date ?? ''); ?>"></label></div><button class="garden-button">Save Assignment</button></form></details>
<details><summary class="garden-disclosure-toggle">Record Progress or Completion</summary><form method="post" action="<?= base_url('garden/work_status'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= (int)$job->id; ?>">
<label>Status<select name="status" data-garden-select hidden><?php foreach (['scheduled'=>'Scheduled','in_progress'=>'In Progress','awaiting_parts'=>'Awaiting Materials','completed'=>'Completed','cancelled'=>'Cancelled / Skipped'] as $value=>$label): ?><option value="<?= $value; ?>"><?= $label; ?></option><?php endforeach; ?></select></label>
<label>Completion / Customer Confirmation Notes<textarea name="resolution_notes" rows="3"></textarea></label><button class="garden-button">Record Status</button></form></details>
<?php if (get_instance()->permissions('items_view')): ?><details><summary class="garden-disclosure-toggle">Record Additional Materials Used</summary><form method="post" action="<?= base_url('garden/work_material'); ?>"><?php $this->load->view('garden/form_token'); ?><input type="hidden" name="job_id" value="<?= (int)$job->id; ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(20)); ?>">
<label>Material<select name="item_id" data-garden-select hidden><option value="">Choose Material</option><?php foreach ($garden_items as $item): if ((int)$item->service_bit===1 || !empty($item->is_bundle)) continue; ?><option value="<?= (int)$item->id; ?>"><?= htmlspecialchars($item->item_name); ?></option><?php endforeach; ?></select></label>
<label>Quantity<input type="number" name="qty" min="0.01" step="0.01" required></label><button class="garden-button">Record Material Issue</button></form></details><?php endif; ?>
<?php endif; ?></article><?php endforeach; ?>
<?php if (!$garden_work): ?><section class="garden-card">No service jobs or visits yet.</section><?php endif; ?>
